1	// Fault-injection shims for the regression-test build of envelopefile.
2	//
3	// This file is linked together with src/main.cpp into the separate
4	// `envelopefile_testable` binary using the linker's --wrap option, so every
5	// open/write/fsync/close call made by the product code is routed through the
6	// __wrap_* functions below. The production binary is completely unaffected.
7	//
8	// Injection is controlled entirely through environment variables so the test
9	// driver can select a scenario per process run:
10	//
11	//   EF_TEST_TARGET          Only inject faults for this exact path. When
12	//                           unset, any file created with O_CREAT|O_EXCL is
13	//                           considered the key file under test.
14	//   EF_TEST_FAIL_WRITE=1    write() on the key file fails with EIO.
15	//   EF_TEST_PARTIAL_WRITE=N write() on the key file returns at most N bytes
16	//                           per call (the caller must loop to complete).
17	//   EF_TEST_FAIL_FSYNC=1    fsync() on the key file fails with EIO.
18	//   EF_TEST_FAIL_CLOSE=1    close() on the key file reports EIO (the
19	//                           descriptor is still really closed, matching the
20	//                           POSIX guarantee that close() releases the fd).
21	//
22	// For deterministic coverage of the write loop itself, a per-call script can
23	// be supplied:
24	//
25	//   EF_TEST_WRITE_SCRIPT=t1,t2,...
26	//                           Each token describes the outcome of one write()
27	//                           call on the key file, consumed in order; once the
28	//                           list is exhausted every further call succeeds
29	//                           normally. Tokens:
30	//                             ok    - write the whole requested buffer
31	//                             N     - short write: at most N (decimal) bytes
32	//                             intr  - fail with EINTR, no bytes written
33	//                             eio   - fail irrecoverably with EIO
34	//                             zero  - return 0 with bytes still pending
35	//
36	//   EF_TEST_WRITE_LOG=path  Record what the write loop actually did, so the
37	//                           test driver can prove byte continuity across
38	//                           retries. On the first key-file write the original
39	//                           32-byte key is snapshotted; every subsequent call
40	//                           is checked to advance from the current offset with
41	//                           a buffer that is a slice of that same snapshot
42	//                           (i.e. the key is neither regenerated, duplicated,
43	//                           nor dropped). The file receives one line:
44	//                             VERIFY <64 lowercase hex digits>
45	//                           followed by one line per write() call:
46	//                             CALL <offset> <requested> <returned> [<errno>]
47	//                           (the errno field is only present when returned is
48	//                           -1). A continuity violation is recorded as a
49	//                             VERIFY-FAILED <reason>
50	//                           line and aborts the process, since it means the
51	//                           product code violated its own write contract.
52	//
53	// Only the file descriptor opened for the key file is instrumented; all
54	// other I/O (stdout, stderr, OpenSSL internals, the log file itself) passes
55	// through untouched.
56	
57	#include <cerrno>
58	#include <cstdarg>
59	#include <cstdint>
60	#include <cstdio>
61	#include <cstdlib>
62	#include <cstring>
63	#include <fcntl.h>
64	#include <unistd.h>
65	
66	extern "C" {
67	
68	// Real libc entry points provided by the --wrap linker mechanism.
69	int __real_open(const char* path, int flags, ...);
70	ssize_t __real_write(int fd, const void* buffer, size_t count);
71	int __real_fsync(int fd);
72	int __real_close(int fd);
73	
74	namespace {
75	
76	constexpr std::size_t kKeyBytes = 32;
77	
78	// Descriptor currently known to belong to the key file under test, or -1.
79	int g_keyFd = -1;
80	
81	// Continuity bookkeeping for EF_TEST_WRITE_LOG.
82	unsigned char g_keySnapshot[kKeyBytes];
83	bool g_haveSnapshot = false;     // the snapshot below is valid
84	std::size_t g_progress = 0;      // bytes acknowledged so far (pre-call offset)
85	
86	bool envFlagSet(const char* name) {
87	    const char* value = std::getenv(name);
88	    return value != nullptr && value[0] != '\0' && std::strcmp(value, "0") != 0;
89	}
90	
91	bool isKeyPath(const char* path) {
92	    const char* target = std::getenv("EF_TEST_TARGET");
93	    return target == nullptr || std::strcmp(path, target) == 0;
94	}
95	
96	bool isKeyFd(int fd) {
97	    return fd != -1 && fd == g_keyFd;
98	}
99	
100	// Preserve errno across the bookkeeping I/O so the injected failure code is
101	// what the product code actually observes.
102	class ErrnoSaver {
103	public:
104	    ErrnoSaver() : saved_(errno) {}
105	    ~ErrnoSaver() { errno = saved_; }
106	
107	private:
108	    int saved_;
109	};
110	
111	void logLine(const char* mode, const char* text) {
112	    const char* logPath = std::getenv("EF_TEST_WRITE_LOG");
113	    if (logPath == nullptr || logPath[0] == '\0') {
114	        return;
115	    }
116	    ErrnoSaver saver;
117	    std::FILE* file = std::fopen(logPath, mode);
118	    if (file == nullptr) {
119	        return;
120	    }
121	    std::fputs(text, file);
122	    std::fputc('\n', file);
123	    std::fclose(file);
124	}
125	
126	void logVerifyHeader(const unsigned char* buffer) {
127	    constexpr std::size_t kPrefix = 7;  // strlen("VERIFY ")
128	    char line[kPrefix + 2 * kKeyBytes + 1];
129	    char* out = line;
130	    std::strcpy(out, "VERIFY ");
131	    out += 7;
132	    static const char hex[] = "0123456789abcdef";
133	    for (std::size_t i = 0; i < kKeyBytes; ++i) {
134	        *out++ = hex[buffer[i] >> 4];
135	        *out++ = hex[buffer[i] & 0x0f];
136	    }
137	    *out = '\0';
138	    logLine("w", line);
139	}
140	
141	void logCall(std::size_t offset, std::size_t requested,
142	             ssize_t returned, int reportedErrno) {
143	    char line[128];
144	    if (returned < 0) {
145	        std::snprintf(line, sizeof(line), "CALL %zu %zu %zd %d",
146	                      offset, requested, returned, reportedErrno);
147	    } else {
148	        std::snprintf(line, sizeof(line), "CALL %zu %zu %zd",
149	                      offset, requested, returned);
150	    }
151	    logLine("a", line);
152	}
153	
154	void logVerifyFailed(const char* reason) {
155	    char line[160];
156	    std::snprintf(line, sizeof(line), "VERIFY-FAILED %s", reason);
157	    logLine("a", line);
158	}
159	
160	// On the first key-file write, snapshot the key; afterwards confirm that the
161	// caller resumes exactly at the acknowledged offset and presents the matching
162	// slice of the same key. Any mismatch is a product-code defect: abort so the
163	// regression run can never pass on a silently regenerated/garbled key.
164	void verifyIncomingBuffer(const void* buffer, std::size_t count) {
165	    if (std::getenv("EF_TEST_WRITE_LOG") == nullptr) {
166	        return;
167	    }
168	    const auto* bytes = static_cast<const unsigned char*>(buffer);
169	    if (!g_haveSnapshot) {
170	        if (count != kKeyBytes) {
171	            logVerifyFailed("first write did not carry the whole 32-byte key");
172	            std::abort();
173	        }
174	        std::memcpy(g_keySnapshot, bytes, kKeyBytes);
175	        g_haveSnapshot = true;
176	        logVerifyHeader(g_keySnapshot);
177	        return;
178	    }
179	    if (g_progress > kKeyBytes) {
180	        logVerifyFailed("offset past end of key");
181	        std::abort();
182	    }
183	    const std::size_t remaining = kKeyBytes - g_progress;
184	    if (count != remaining) {
185	        logVerifyFailed("write length does not match the bytes still pending");
186	        std::abort();
187	    }
188	    if (std::memcmp(g_keySnapshot + g_progress, bytes, remaining) != 0) {
189	        logVerifyFailed("buffer is not the same key (key was regenerated?)");
190	        std::abort();
191	    }
192	}
193	
194	void resetWriteBookkeeping() {
195	    g_haveSnapshot = false;
196	    g_progress = 0;
197	}
198	
199	// Outcome of one scripted write() call.
200	enum class WriteOutcome {
201	    kPass,       // behave as the real syscall with the given count
202	    kShort,      // behave as the real syscall but cap the count
203	    kEintr,      // report a recoverable interrupt, nothing written
204	    kEio,        // report an irrecoverable I/O error
205	    kZero,       // report zero bytes with data still pending
206	};
207	
208	struct ScriptedCall {
209	    WriteOutcome outcome;
210	    long limit;  // valid for kShort
211	};
