```cpp
// ---- secure-random failure injection -------------------------------------
//
//   EF_TEST_FAIL_RAND=1       RAND_bytes reports failure (returns 0).
//   EF_TEST_RAND_PARTIAL=N    before failing, N marker bytes (0xA5) are
//                             written into the caller's buffer, simulating a
//                             CSPRNG that dies mid-fill.
//   EF_TEST_RAND_ERROR_DETAIL=1
//                             leave a descriptive OpenSSL error on the
//                             thread's error queue; otherwise the queue is
//                             cleared so the failure carries no detail.
//   EF_TEST_KEY_LOG=path      record key-buffer lifecycle events, one per
//                             line:
//                               RAND <requested> partial=<N> result=<ok|fail>
//                               CLEANSED-KEY <len>
//                             The CLEANSED-KEY line proves the key buffer
//                             (including any partial bytes) was wiped.

unsigned char* g_randBuf = nullptr;
int g_randBufSize = 0;

int __wrap_RAND_bytes(unsigned char* buf, int num) {
    if (!envFlagSet("EF_TEST_FAIL_RAND")) {
        return __real_RAND_bytes(buf, num);
    }
    g_randBuf = buf;
    g_randBufSize = num;
    long partial = 0;
    const char* raw = std::getenv("EF_TEST_RAND_PARTIAL");
    if (raw != nullptr) {
        partial = std::atol(raw);
        if (partial < 0) partial = 0;
        if (partial > num) partial = num;
    }
    for (long i = 0; i < partial; ++i) buf[i] = 0xA5;
    ERR_clear_error();
    if (envFlagSet("EF_TEST_RAND_ERROR_DETAIL")) {
        // raise
    }
    // log
    char line[128];
    std::snprintf(line, sizeof line, "RAND %d partial=%ld result=fail", num, partial);
    logKeyLine(line);
    return 0;
}

void __wrap_OPENSSL_cleanse(void* ptr, size_t len) {
    if (ptr == g_randBuf && g_randBuf != nullptr) {
        char line[64];
        std::snprintf(line, sizeof line, "CLEANSED-KEY %zu", len);
        logKeyLine(line);
        g_randBuf = nullptr;  // avoid stale pointer matches
    }
    __real_OPENSSL_cleanse(ptr, len);
}
```

